Input: {"question": "When was Stephen O'Mara born?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0121-1fbb6efea06e:d00", "start": 0, "end": 10, "text": "Stephen M."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0121-1fbb6efea06e:d00", "start": 11, "end": 137, "text": "O'Mara Stephen Mary O'Mara (5 January 1884 – 11 November 1959) was an Irish businessman and republican politician in Limerick."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0121-1fbb6efea06e:d00", "start": 138, "end": 258, "text": "O'Mara was the third son of Stephen O'Mara, Snr, a former Mayor of Limerick and briefly an Irish Parliamentary Party MP."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0121-1fbb6efea06e:d00", "start": 259, "end": 270, "text": "Stephen Jr."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0121-1fbb6efea06e:d00", "start": 271, "end": 314, "text": "married Nancy O'Brien and had a son, Peter."}, "D1S6": {"document_number": 1, "doc_id": "ramdocs-0121-1fbb6efea06e:d00", "start": 315, "end": 426, "text": "His elder brother James was an early supporter of Sinn Féin, which Stephen also joined after the Easter Rising."}, "D1S7": {"document_number": 1, "doc_id": "ramdocs-0121-1fbb6efea06e:d00", "start": 427, "end": 508, "text": "He was a member of Limerick Corporation when the Irish War of Independence began."}, "D1S8": {"document_number": 1, "doc_id": "ramdocs-0121-1fbb6efea06e:d00", "start": 509, "end": 582, "text": "The Mayor of Limerick, George Clancy, was killed by the Black and Tans on"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0121-1fbb6efea06e:d01", "start": 0, "end": 143, "text": "Stephen O'Mara (senator) Stephen O'Mara MP (26 December 1844 – 26 July 1926) was an Irish nationalist politician and businessman from Limerick."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0121-1fbb6efea06e:d01", "start": 144, "end": 249, "text": "O'Mara's father James O'Mara was an early supporter of Isaac Butt, and owned a bacon factory in the city."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0121-1fbb6efea06e:d01", "start": 250, "end": 286, "text": "Stephen entered the family business."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0121-1fbb6efea06e:d01", "start": 287, "end": 336, "text": "His brother Joseph O'Mara became an opera singer."}, "D2S5": {"document_number": 2, "doc_id": "ramdocs-0121-1fbb6efea06e:d01", "start": 337, "end": 374, "text": "Stephen married Ellen Pigott in 1867."}, "D2S6": {"document_number": 2, "doc_id": "ramdocs-0121-1fbb6efea06e:d01", "start": 375, "end": 448, "text": "They had 12 children, of whom the first three died of diphtheria in 1872."}, "D2S7": {"document_number": 2, "doc_id": "ramdocs-0121-1fbb6efea06e:d01", "start": 449, "end": 565, "text": "Sons James and Stephen, Jnr became prominent Irish republicans and radicalised their father's later political views."}, "D2S8": {"document_number": 2, "doc_id": "ramdocs-0121-1fbb6efea06e:d01", "start": 566, "end": 645, "text": "O'Mara joined Limerick Corporation c.1880, becoming the first Nationalist Mayor"}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0121-1fbb6efea06e:d02", "start": 0, "end": 12, "text": "a teenager ."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0121-1fbb6efea06e:d02", "start": 13, "end": 120, "text": "She graduated from the Interboro High School in 2007 and became the first in her family to attend college ."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0121-1fbb6efea06e:d02", "start": 121, "end": 254, "text": "[ 2 ] She earned a Bachelor of Arts degree in history and a certificate in Secondary Education from West Chester University in 2011 ."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0121-1fbb6efea06e:d02", "start": 255, "end": 433, "text": "In 2017 , She received a Master 's degree in liberal studies from the University of Pennsylvania , her master 's thesis was centered around creative methods for childhood grief ."}, "D3S5": {"document_number": 3, "doc_id": "ramdocs-0121-1fbb6efea06e:d02", "start": 434, "end": 525, "text": "[ 3 ] [ 4 ] Pennsylvania House of Representatives [ edit ] Elections [ edit ] 2018 [ edit ]"}}, "original_cards": [{"doc_id": "ramdocs-0121-1fbb6efea06e:d00", "card_id": "ramdocs-0121-1fbb6efea06e:d00:c0", "entity": "Stephen O'Mara", "scope": "birth date", "claim": "Stephen O'Mara was born on 5 January 1884.", "answer": "5 January 1884", "quote": "O'Mara Stephen Mary O'Mara (5 January 1884 – 11 November 1959) was an Irish businessman and republican politician in Limerick.", "original_document_number": 1}, {"doc_id": "ramdocs-0121-1fbb6efea06e:d01", "card_id": "ramdocs-0121-1fbb6efea06e:d01:c0", "entity": "Stephen O'Mara", "scope": "birth date", "claim": "Stephen O'Mara was born on 26 December 1844.", "answer": "26 December 1844", "quote": "Stephen O'Mara (senator) Stephen O'Mara MP (26 December 1844 – 26 July 1926) was an Irish nationalist politician and businessman from Limerick.", "original_document_number": 2}], "current_answers": ["5 January 1884", "26 December 1844"], "candidate_answers": [{"candidate_id": "R0", "answer": "5 January 1884", "origin": "initial"}, {"candidate_id": "R1", "answer": "26 December 1844", "origin": "initial"}], "requested_slot_hint": "birth_date"}
